--- FILE: src/agent/index.ts ---
Range: 1 - 220

1 | /**
2 |  * Agent - AI 代理
3 |  * 负责编排 LLM 调用和会话管理
4 |  *
5 |  * 注意：此文件是旧版 Agent，建议使用 index-eventbus.ts 以获得 EventBus 集成
6 |  * 要启用 EventBus 功能，请导入 './index-eventbus' 而不是此文件
7 |  */
8 | import EventEmitter from "events";
9 | import { LLMProvider, LLMResponse, Message, ToolCall, ToolSchema } from "../providers/base";
10 | import { ScopedLogger } from "../util/log";
11 | import { SessionManager } from "../session-v2";
12 | import { ToolRegistry } from "../tool/registry";
13 | 
14 | export interface AgentConfig {
15 |     llmProvider: LLMProvider;
16 |     sessionManager: SessionManager;
17 |     systemPrompt: string;
18 |     /** 默认工具列表（可选），不传则使用 ToolRegistry 中所有工具 */
19 |     defaultTools?: ToolSchema[];
20 |     /** 最大循环次数，防止无限循环，默认 1024 */
21 |     maxLoop?: number;
22 |     /** 最大 token 数，默认 8000 */
23 |     maxTokens?: number;
24 |     /** 最大输出 token 数，默认 8000 */
25 |     maxOutputTokens?: number;
26 |     /** 工具并发上限，默认 1 */
27 |     toolConcurrency?: number;
28 |     /** 单次工具调用超时（毫秒），默认 300000 (5分钟) */
29 |     toolTimeoutMs?: number;
30 |     /** 连续错误次数上限，默认 2 */
31 |     noProgressLimit?: number;
32 | }
33 | 
34 | export interface AgentResponse {
35 |     content: string;
36 |     role: Message['role'];
37 |     type?: Message['type'];
38 | }
39 | 
40 | export default class Agent extends EventEmitter {
41 |     private llmProvider: LLMProvider;
42 |     private logger: ScopedLogger;
43 |     private sessionManager: SessionManager;
44 |     private systemPrompt: string;
45 |     private defaultTools: ToolSchema[] | undefined;
46 |     private maxLoop: number;
47 |     maxOutputTokens: number;
48 |     maxTokens: number;
49 |     private noProgressLimit: number;
50 | 
51 |     constructor(config: AgentConfig) {
52 |         super();
53 |         this.llmProvider = config.llmProvider;
54 |         this.sessionManager = config.sessionManager;
55 |         this.systemPrompt = config.systemPrompt;
56 |         this.defaultTools = config.defaultTools;
57 |         this.logger = new ScopedLogger('Agent');
58 |         this.maxLoop = config.maxLoop ?? 1024;
59 | 
60 |         const providerMaxOutput = this.llmProvider.maxOutputTokens;
61 |         const providerMaxTokens = this.llmProvider.maxTokens;
62 |         this.maxOutputTokens = Math.min(config.maxOutputTokens ?? providerMaxOutput, providerMaxOutput);
63 |         this.maxTokens = Math.min(config.maxTokens ?? providerMaxTokens, providerMaxTokens);
64 |         this.noProgressLimit = Math.max(0, config.noProgressLimit ?? 2);
65 | 
66 |         this.sessionManager.maxOutputTokens = this.maxOutputTokens;
67 |         this.sessionManager.maxTokens = this.maxTokens;
68 |     }
69 | 
70 |     /**
71 |      * 执行单个工具调用
72 |      */
73 |     private async executeToolCall(toolCall: ToolCall): Promise<Message> {
74 |         const { name, arguments: args } = toolCall.function;
75 |         if (!name) {
76 |             return {
77 |                 role: 'tool',
78 |                 type: 'text',
79 |                 content: 'Error: Tool name is empty',
80 |                 tool_call_id: toolCall.id,
81 |             };
82 |         }
83 | 
84 |         const result = await ToolRegistry.execute(name, args);
85 | 
86 |         let content: string;
87 |         if (typeof result === 'string') {
88 |             content = result;
89 |         } else {
90 |             content = JSON.stringify(result?.metadata ?? result ?? {});
91 |         }
92 | 
93 |         return {
94 |             role: 'tool',
95 |             type: 'text',
96 |             content,
97 |             tool_call_id: toolCall.id,
98 |         };
99 |     }
100 | 
101 |     /**
102 |      * 处理工具调用，返回是否有工具被调用
103 |      */
104 |     private async handleToolCalls(
105 |         llmResponse: LLMResponse,
106 |         spinner: ReturnType<ScopedLogger['spinner']>
107 |     ): Promise<boolean> {
108 |         if (!llmResponse.tool_calls || llmResponse.tool_calls.length === 0) {
109 |             return false;
110 |         }
111 | 
112 |         const toolResults = await Promise.all(
113 |             llmResponse.tool_calls.map(call => this.executeToolCall(call))
114 |         );
115 | 
116 |         this.sessionManager.addMessage(toolResults);
117 | 
118 |         // Bug修复：提取content字段进行拼接，而非直接join对象数组
119 |         const summaries = toolResults
120 |             .map(r => {
121 |                 const content = r.content ?? '';
122 |                 return content.length > 50 ? content.slice(0, 47) + '...' : content;
123 |             })
124 |             .join(', ');
125 | 
126 |         spinner.succeed(`Tool calls: ${summaries}`);
127 |         return true;
128 |     }
129 | 
130 |     /**
131 |      * 运行 Agent 处理用户查询
132 |      * @param query 用户查询
133 |      * @param options 选项
134 |      * @returns Agent 响应
135 |      */
136 |     async run(
137 |         query: string,
138 |         options?: { silent?: boolean; tools?: ToolSchema[] }
139 |     ): Promise<AgentResponse | null> {
140 |         const tools = options?.tools ?? this.defaultTools ?? [];
141 |         let consecutiveErrorCount = 0;
142 | 
143 |         // 添加用户消息
144 |         this.sessionManager.addMessage({
145 |             role: 'user',
146 |             type: 'text',
147 |             content: query,
148 |         });
149 | 
150 |         for (let i = 0; i < this.maxLoop; i++) {
151 |             const llmMessages = await this.sessionManager.getMessages();
152 |             const spinner = this.logger.spinner(`Thinking-${i + 1}...`);
153 | 
154 |             try {
155 |                 const llmResponse = await this.llmProvider.generate(
156 |                     [
157 |                         { role: 'system', content: this.systemPrompt },
158 |                         ...llmMessages,
159 |                     ],
160 |                     {
161 |                         model: process.env.AI_MODEL,
162 |                         tools: tools.length > 0 ? tools : undefined,
163 |                         max_tokens: this.maxOutputTokens,
164 |                     }
165 |                 );
166 | 
167 |                 if (!llmResponse) {
168 |                      throw new Error('LLM response is null');
169 |                 }
170 |                   
171 |                 this.sessionManager.addMessage(llmResponse);
172 | 
173 |                 const hasToolCalls = await this.handleToolCalls(llmResponse, spinner);
174 |                 
175 |                 if (!hasToolCalls) {
176 |                     // 最终文本响应
177 |                     const finalResponse: AgentResponse = {
178 |                         content: llmResponse?.content ?? '',
179 |                         role: 'assistant',
180 |                         type: 'text',
181 |                     };
182 | 
183 |                     spinner.succeed(finalResponse.content);
184 |                     this.sessionManager.addMessage(finalResponse);
185 |                     return finalResponse;
186 |                 }
187 | 
188 |                 // 工具调用成功，重置连续错误计数
189 |                 consecutiveErrorCount = 0;
190 | 
191 |             } catch (error) {
192 |                 const errorMsg = error instanceof Error ? error.message : String(error);
193 |                 spinner.fail(errorMsg);
194 |                 this.logger.error(`LLM call failed: ${errorMsg}`);
195 | 
196 |                 this.sessionManager.addMessage({
197 |                     role: 'assistant',
198 |                     type: 'text',
199 |                     content: `LLM error: ${errorMsg}`,
200 |                 });
201 | 
202 |                 consecutiveErrorCount++;
203 | 
204 |                 if (consecutiveErrorCount > this.noProgressLimit) {
205 |                     return {
206 |                         content: `Max error limit reached: ${errorMsg}`,
207 |                         role: 'assistant',
208 |                     };
209 |                 }
210 |             }
211 |         }
212 | 
213 |         // Bug修复：循环达到上限时返回错误信息
214 |         return {
215 |             content: 'Error :Agent reached maximum loop limit without completion',
216 |             role: 'assistant',
217 |         };
218 |     }
219 | }
